126	    /**
127	     * The owner's age band derived from {@link #birthDate}, computed against the
128	     * {@link #registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"} when
129	     * 18 to 64 inclusive, {@code "SENIOR"} when 65 or over. Null when either the birth
130	     * date or the registration date is absent.
131	     */
132	    @Transient
133	    public String getAgeBand() {
134	        if (this.birthDate == null || this.registrationDate == null) {
135	            return null;
136	        }
137	        int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
138	        if (age < 18) {
139	            return "MINOR";
140	        }
141	        if (age < 65) {
142	            return "ADULT";
143	        }
144	        return "SENIOR";
