187	    /**
188	     * The owner's name formatted for display as {@code "LastName, FirstName"}.
189	     */
190	    @Transient
191	    public String getDisplayName() {
192	        return this.getLastName() + ", " + this.getFirstName();
193	    }
194	
195	    /**
196	     * The owner's initials: the upper-cased first letters of firstName and
197	     * lastName, dot-separated with a trailing dot (e.g. {@code "J.S."}).
198	     */
199	    @Transient
200	    public String getInitials() {
201	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
202	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
203	    }
204	
205	    /**
206	     * The owner's membership number, formatted {@code "<customerCode>-M<YY>"} where
207	     * YY is the last two digits of the registration date's year
208	     * (e.g. {@code "NSW-A1B2C3D4-M26"}). Derived from the owner's own fields; null when
209	     * either the customer code or registration date is absent.
210	     */
211	    @Transient
212	    public String getMembershipNumber() {
213	        if (this.customerCode == null || this.registrationDate == null) {
214	            return null;
215	        }
216	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
217	    }
218	
219	    /**
220	     * The owner's check digit: a single Luhn check digit (0-9) computed over the digits
221	     * contained in the {@code customerCode}, scanning right to left and doubling the
222	     * rightmost digit first; non-digit characters are ignored. Derived from the owner's
223	     * own fields; null when the customer code is absent.
224	     */
225	    @Transient
226	    public Integer getCheckDigit() {
227	        if (this.customerCode == null) {
228	            return null;
229	        }
230	        int sum = 0;
231	        boolean dbl = true;
232	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
233	            char c = this.customerCode.charAt(i);
234	            if (c < '0' || c > '9') {
235	                continue;
236	            }
237	            int d = c - '0';
238	            if (dbl) {
239	                d *= 2;
240	                if (d > 9) {
241	                    d -= 9;
242	                }
243	            }
244	            sum += d;
245	            dbl = !dbl;
246	        }
247	        return (10 - (sum % 10)) % 10;
248	    }
249	
250	    /**
251	     * The owner's membership level: a number from 1 to 3 assigned at creation. Starts
252	     * at 1, gains 1 when an email address is present, gains a further 1 when the owner
253	     * has no namesakes ({@code namesakeCount} is 0), and is capped at 3 (level 4 is
254	     * reserved for tenure). Derived from the owner's own fields.
255	     */
256	    @Transient
257	    public Integer getMembershipLevel() {
258	        int level = 1;
259	        boolean hasEmail = this.email != null && !this.email.isBlank();
260	        if (hasEmail) {
261	            level++;
262	        }
263	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
264	        if (unique) {
265	            level++;
266	        }
267	        return Math.min(level, 3);
268	    }
