270	    /**
271	     * Fixed city-to-region lookup table. Any city not listed derives locality
272	     * {@code "UNKNOWN"}.
273	     */
274	    private static final Map<String, String> CITY_REGION = Map.of(
275	        "Sydney", "NSW",
276	        "Melbourne", "VIC",
277	        "Brisbane", "QLD");
278	
279	    /**
280	     * Region -> inclusive 4-digit postcode range {low, high}: NSW 2000-2099,
281	     * VIC 3000-3099, QLD 4000-4099. The single source of truth for the
282	     * postcode-to-region mapping, consulted by {@link #regionForPostcode(String)}
283	     * (used by locality derivation) and {@link #hasPostcodeRange(String)} (used by
284	     * postcode validation).
285	     */
286	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
287	        "NSW", new int[] {2000, 2099},
288	        "VIC", new int[] {3000, 3099},
289	        "QLD", new int[] {4000, 4099});
290	
291	    /**
292	     * The owner's locality: the REGION component of the owner's region-and-hash identity.
293	     * Read off the {@code customerCode} prefix (the part before the first {@code '-'}) when
294	     * a customer code is present, otherwise derived straight from the postcode via
295	     * {@link #identityRegion(String)}. Either way this yields the region the customer code
296	     * was built from — NSW/VIC/QLD, or {@code "UNKNOWN"} when the postcode is absent or in
297	     * no known range. Derived from the owner's own fields.
298	     */
299	    @Transient
300	    public String getLocality() {
301	        if (this.customerCode != null) {
302	            int dash = this.customerCode.indexOf('-');
303	            if (dash > 0) {
304	                return this.customerCode.substring(0, dash);
305	            }
306	        }
307	        return identityRegion(this.postcode);
308	    }
309	
310	    /**
311	     * The REGION component of an owner's region-and-hash identity: the region derived from
312	     * the postcode via {@link #regionForPostcode(String)} (NSW/VIC/QLD), or
313	     * {@code "UNKNOWN"} when the postcode is absent or in no known range. The single source
314	     * of truth for the identity's region, so the {@code customerCode} prefix and the
315	     * {@link #getLocality() locality} cannot drift apart.
316	     */
317	    public static String identityRegion(String postcode) {
318	        String region = regionForPostcode(postcode);
319	        return region != null ? region : "UNKNOWN";
320	    }
321	
322	    /**
323	     * The canonical region for a city per the fixed city-to-region table
324	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), or
325	     * {@code "UNKNOWN"} when the city is not in the table. The single source of truth
326	     * for the city-to-region mapping, used as the city's region in postcode validation.
327	     */
328	    public static String regionForCity(String city) {
329	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
330	    }
331	
332	    /**
333	     * The canonical region for a 4-digit postcode per the fixed range table
334	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), or {@code null} when the postcode
335	     * is absent, not a well-formed integer, or in no known range. Reads the shared
336	     * {@link #REGION_POSTCODE_RANGES} table; used by {@link #identityRegion(String)}
337	     * for the identity's region and by postcode validation to range-check a submitted
338	     * postcode against its city's region.
339	     */
340	    public static String regionForPostcode(String postcode) {
341	        if (postcode == null) {
342	            return null;
343	        }
344	        int value;
345	        try {
346	            value = Integer.parseInt(postcode.trim());
347	        } catch (NumberFormatException ex) {
348	            return null;
349	        }
350	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
351	            int[] range = entry.getValue();
352	            if (value >= range[0] && value <= range[1]) {
353	                return entry.getKey();
354	            }
355	        }
356	        return null;
357	    }
358	
359	    /**
360	     * Whether the region is subject to postcode range validation, i.e. has a known
361	     * range in the shared {@link #REGION_POSTCODE_RANGES} table. A region with no range
362	     * (including {@code "UNKNOWN"}) accepts any well-formed postcode.
363	     */
364	    public static boolean hasPostcodeRange(String region) {
365	        return REGION_POSTCODE_RANGES.containsKey(region);
366	    }
367	
368	    /**
369	     * The owner's preferred contact channel: {@code "EMAIL"} when an email address is
370	     * present, otherwise {@code "PHONE"}. Derived from the owner's own fields.
371	     */
372	    @Transient
373	    public String getContactPreference() {
374	        boolean hasEmail = this.email != null && !this.email.isBlank();
375	        return hasEmail ? "EMAIL" : "PHONE";
376	    }
377	
378	    /**
379	     * The owner's identity key: the single value that duplicate detection is expressed
380	     * through, formed as {@code normalizedTelephone + "|" + (email or empty) + "|" +
381	     * (householdId or empty)}. The telephone and email are already stored in their
382	     * normalized forms (E.164 and lower-cased), and the household id is empty for a solo
383	     * owner. Two owners are duplicates only when their whole identity keys are equal, so
384	     * two members of the same household with different telephones have distinct keys.
385	     * Derived from the owner's own fields.
386	     */
387	    @Transient
388	    public String getIdentityKey() {
389	        return identityKey(this.telephone, this.email, this.householdId);
390	    }
391	
392	    /**
393	     * Composes an identity key from its already-normalized parts. The single place the
394	     * key's shape is defined, so the create-time duplicate check (which normalizes a
395	     * request's parts) and this entity's {@link #getIdentityKey()} cannot drift apart. A
396	     * null or blank part contributes an empty segment.
397	     */
398	    public static String identityKey(String normalizedTelephone, String normalizedEmail, String householdId) {
399	        return keyPart(normalizedTelephone) + "|" + keyPart(normalizedEmail) + "|" + keyPart(householdId);
400	    }
401	
402	    private static String keyPart(String value) {
403	        return (value == null || value.isBlank()) ? "" : value;
404	    }
405	
406	    protected Set<Pet> getPetsInternal() {
407	        if (this.pets == null) {
408	            this.pets = new HashSet<>();
409	        }
410	        return this.pets;
411	    }
412	
413	    protected void setPetsInternal(Set<Pet> pets) {
414	        this.pets = pets;
415	    }
416	
417	    public List<Pet> getPets() {
418	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
419	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
420	        return Collections.unmodifiableList(sortedPets);
421	    }
422	
423	    public void setPets(List<Pet> pets) {
424	        this.pets = new HashSet<>(pets);
425	    }
426	
427	    public void addPet(Pet pet) {
428	        getPetsInternal().add(pet);
429	        pet.setOwner(this);
430	    }
431	
432	    /**
433	     * Return the Pet with the given name, or null if none found for this Owner.
434	     *
435	     * @param name to test
436	     * @return true if pet name is already in use
437	     */
438	    public Pet getPet(String name) {
439	        return getPet(name, false);
440	    }
441	
442	    /**
443	     * Return the Pet with the given name, or null if none found for this Owner.
444	     *
445	     * @param name to test
446	     * @return true if pet name is already in use
447	     */
448	    public Pet getPet(String name, boolean ignoreNew) {
449	        name = name.toLowerCase();
450	        for (Pet pet : getPetsInternal()) {
451	            if (!ignoreNew || !pet.isNew()) {
452	                String compName = pet.getName();
453	                compName = compName.toLowerCase();
454	                if (compName.equals(name)) {
455	                    return pet;
456	                }
457	            }
458	        }
459	        return null;
460	    }
461	
462	    public Pet getPet(Integer petId) {
463	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
464	    }
465	
466	    @Override
467	    public String toString() {
468	        return new ToStringCreator(this)
469	
470	            .append("id", this.getId())
471	            .append("new", this.isNew())
472	            .append("lastName", this.getLastName())
473	            .append("firstName", this.getFirstName())
474	            .append("address", this.address)
475	            .append("city", this.city)
476	            .append("telephone", this.telephone)
477	            .append("email", this.email)
478	            .toString();
479	    }
480	}
